func TestFlip(t *testing.T) {
	for _, tc := range []struct {
		input bool
		want  bool
	}{
		{false, true},
		{true, false},
	} {
		if got := Flip(tc.input); got != tc.want {
			t.Fatalf("Flip(%v) = %v; want %v", tc.input, got, tc.want)
		}
	}
}

